import os
from typing import Optional

from openai import OpenAI


def answer_question_with_context(question: str, context: str, model: Optional[str] = None) -> str:
    client = OpenAI(api_key=os.getenv("OPENAI_API_KEY"))
    model_id = model or os.getenv("OPENAI_MODEL", "gpt-4o-mini")

    messages = [
        {
            "role": "system",
            "content": "Answer the user's question using only the provided context. If the context does not contain the answer, say you don't know.",
        },
        {
            "role": "user",
            "content": f"Context:\n{context}\n\nQuestion:\n{question}",
        },
    ]

    response = client.chat.completions.create(
        model=model_id,
        messages=messages,
        temperature=0,
    )

    return (response.choices[0].message.content or "").strip()
